def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Encourage stacks with more free space, lower average ID, fewer blocking containers
    # Apply a logarithmic penalty for stack height imbalance for smoother balancing
    if SH == 0:
        log_penalty = 0  # No penalty for empty stacks
    else:
        log_penalty = 1 + abs((SH - 1) / (SH)) * (1 + (SH - 1))  # Log-like penalty based on deviation from ideal height
    priority = (10 - EMP) * 0.3 + AVG * 0.2 + RI * 0.2 + log_penalty * 0.3
    return priority
